import React, { useState } from 'react';
import axios from 'axios';
import loginImage from '../login.png'; 

const Login = ({ setShowLoginModal, handleLoginSubmit }) => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');

    const handleSubmit = (e) => {
        e.preventDefault();
        handleLoginSubmit(username, password);
    };

    return (
        <div style={{
            position: 'fixed', top: 0, left: 0, width: '100%', height: '100%',
            background: 'rgba(0,0,0,0.6)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000
        }}>
            <div style={{ background: '#fff', padding: '30px', borderRadius: '15px', width: '350px', textAlign: 'center', boxShadow: '0 4px 15px rgba(0,0,0,0.3)' }}>
                <img src={loginImage} alt="Logo" style={{ width: '80px', height: '80px', marginBottom: '15px' }} />
                
                <h2>Welcome to Aura Pen</h2>
                
                <form onSubmit={handleSubmit}>
                    <input type="text" placeholder="Student ID" onChange={(e) => setUsername(e.target.value)} 
                        style={{ width: '90%', padding: '10px', marginBottom: '10px', borderRadius: '5px', border: '1px solid #ccc' }} required />
                    
                    <input type="password" placeholder="Password" onChange={(e) => setPassword(e.target.value)} 
                        style={{ width: '90%', padding: '10px', marginBottom: '20px', borderRadius: '5px', border: '1px solid #ccc' }} required />
                    
                    <button type="submit" style={{ width: '100%', padding: '10px', background: '#27ae60', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', fontSize: '16px' }}>
                        Login
                    </button>
                    
                    <button type="button" onClick={() => setShowLoginModal(false)} 
                        style={{ width: '100%', padding: '10px', marginTop: '10px', background: '#e74c3c', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer' }}>
                        Cancel
                    </button>
                </form>
            </div>
        </div>
    );
};

export default Login;
